#include <string>
using namespace std;

class Solution {
public:
    bool checkOnesSegment(string s) {
        return s.find("01") == string::npos;
    }
};

class Solution {
    public boolean checkOnesSegment(String s) {
        return !s.contains("01");
    }
}
